/* ==========================================================================
   주인공 도트 스프라이트 (참고 스프라이트 시트: 초록 머리 · 연두·흰 도포에 금 테두리 · 언월도)
   · 앞(down)·왼쪽(left)·오른쪽(right)·뒤(up) 4방향. 서 있기 · 걷기 · 달리기(Shift) 그림을 시트에서 잘라 72×64 도트로 줄여 넣었다.
   · 걷기는 같은 자세의 걷기 한 장과 서 있는 그림을 번갈아 쓴다(시트의 나머지 걷기 그림은 방향이 제각각이라 뺐다). 달리기는 앞·옆만 있고, 뒤는 걷기를 빠르게 쓴다.
   · 캔버스 72×64, 머리 중심 x=36, 발끝 y=63.
   ========================================================================== */
const HERO = (() => {
  const PW = 72, PH = 64;
  const DATA = {
    'down.idle': 'data:image/png;base64,',
    'down.w0': 'data:image/png;base64,',
    'down.w1': 'data:image/png;base64,',
    'down.w2': 'data:image/png;base64,',
    'down.run': 'data:image/png;base64,',
    'left.idle': 'data:image/png;base64,',
    'left.w0': 'data:image/png;base64,',
    'left.w1': 'data:image/png;base64,',
    'left.w2': 'data:image/png;base64,',
    'left.run': 'data:image/png;base64,',
    'right.idle': 'data:image/png;base64,',
    'right.w0': 'data:image/png;base64,',
    'right.w1': 'data:image/png;base64,',
    'right.w2': 'data:image/png;base64,',
    'right.run': 'data:image/png;base64,',
    'up.idle': 'data:image/png;base64,',
    'up.w0': 'data:image/png;base64,'
  };
  const mk = (key, dy = 0) => { const c = document.createElement('canvas'); c.width = PW; c.height = PH; const im = new Image(); im.onload = () => { const g = c.getContext('2d'); g.imageSmoothingEnabled = false; g.drawImage(im, 0, dy); }; im.src = DATA[key]; return c; };
  const FR = {};      // 불러오자마자 미리 만들어 둔다(진입 전에 이미 그려져 있음)
  // 시트의 걷기 중간 그림은 방향·창 위치가 제각각이라 번갈아 쓰면 몸이 휙휙 돌아 보인다.
  // 그래서 같은 자세(창이 같은 쪽에 있고 같은 방향을 보는) 걷기 한 장 + 서 있는 그림을 번갈아 쓰고, 서 있는 쪽은 1칸 위로 띄워 걸음의 오르내림을 만든다.
  const walk = (w, i) => [mk(w), mk(i, -1), mk(w), mk(i, -1)];
  const dirs = {
    down: { idle: mk('down.idle'), walk: walk('down.w0', 'down.idle'), run: null },
    // 시트의 LEFT/RIGHT 는 캐릭터 기준이라 화면에서는 반대로 보인다(LEFT 그림은 오른쪽을 본다) → 서로 바꿔 쓴다
    right: { idle: mk('left.idle'), walk: walk('left.w2', 'left.idle'), run: [mk('left.run'), mk('left.run', -2)] },
    left: { idle: mk('right.idle'), walk: walk('right.w0', 'right.idle'), run: [mk('right.run'), mk('right.run', -2)] },
    up: { idle: mk('up.idle'), walk: walk('up.w0', 'up.idle'), run: null },
  };
  return { PW, PH, build: () => dirs };
})();
